cat > src/landing.css <<'EOF'
/* page-constructor не поставляет reset: без него отступы контейнера сетки
   вылезают за вьюпорт по горизонтали. */
*,
*::before,
*::after {
  box-sizing: border-box;
}
EOF
cat > src/App.tsx <<'EOF'
import '@gravity-ui/page-constructor/styles/styles.scss';
import './landing.css';

import { PageConstructor, PageConstructorProvider } from '@gravity-ui/page-constructor';

import { content } from './content';

export function App() {
  return (
    <PageConstructorProvider locale={{ lang: 'ru' }}>
      <PageConstructor content={content} />
    </PageConstructorProvider>
  );
}
EOF
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  plugins: [
    react(),
    // Требуется page-constructor: динамические импорты блоков под Vite.
    dynamicImport({
      filter: (id) => id.includes('/node_modules/@gravity-ui/page-constructor'),
    }),
  ],
});
EOF
timeout 280 npm run build 2>&1 | tail -40

cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  plugins: [
    react(),
    // Требуется page-constructor: динамические импорты блоков под Vite.
    dynamicImport({
      filter: (id) => id.includes('/node_modules/@gravity-ui/page-constructor'),
    }),
  ],
  resolve: {
    // CSS page-constructor использует webpack-префикс `~` в @import;
    // Vite его не понимает, поэтому разворачиваем только эти два пакета.
    alias: [
      { find: /^~@diplodoc\/transform\//, replacement: '@diplodoc/transform/' },
      { find: /^~@gravity-ui\/uikit\//, replacement: '@gravity-ui/uikit/' },
    ],
  },
});
EOF
timeout 280 npm run build 2>&1 | grep -vE "DEPRECATION|More info|^\s*[╷│╵]|^\s*$|node_modules/.*@import|^\s+@import" | tail -25
